function temperatureFinale(etapes) {
  let temperature = 0;
  for (const etape of etapes) {
    if (etape[0] === "chauffer") {
      temperature = temperature + etape[1];
    } else {
      temperature = temperature - etape[1];
    }
    if (temperature < 0) {
      temperature = 0;
    }
  }
  return temperature;
}

