solution.javascript:
function dicterRecette(paroles) {
  const recette = [];
  const annules = [];
  for (const parole of paroles) {
    if (parole === "annuler") {
      if (recette.length > 0) {
        annules.push(recette.pop());
      }
    } else if (parole === "refaire") {
      if (annules.length > 0) {
        recette.push(annules.pop());
      }
    } else {
      recette.push(parole);
      annules.length = 0;
    }
  }
  return recette;
}

