def dicter_recette(paroles):
    recette = []
    annules = []
    for parole in paroles:
        if parole == "annuler":
            if recette:
                annules.append(recette.pop())
        elif parole == "refaire":
            if annules:
                recette.append(annules.pop())
        else:
            recette.append(parole)
            annules.clear()
    return recette

