solution.javascript:
function premiereErreur(texte) {
  const ouvrants = "([{";
  const fermants = ")]}";
  const pile = [];
  let guillemet = -1;
  for (let i = 0; i < texte.length; i++) {
    const c = texte[i];
    if (guillemet !== -1) {
      if (c === "\\") {
        i++;
      } else if (c === '"') {
        guillemet = -1;
      }
    } else if (c === '"') {
      guillemet = i;
    } else if (ouvrants.includes(c)) {
      pile.push(i);
    } else if (fermants.includes(c)) {
      if (pile.length === 0 || ouvrants.indexOf(texte[pile[pile.length - 1]]) !== fermants.indexOf(c)) {
        return i;
      }
      pile.pop();
    }
  }
  if (guillemet !== -1) {
    return guillemet;
  }
  return pile.length > 0 ? pile[pile.length - 1] : -1;
}

