    while i < len(texte):
        c = texte[i]
        if guillemet != -1:
            if c == "\\":
                i += 1
            elif c == '"':
                guillemet = -1
        elif c == '"':
            guillemet = i
        elif c in ouvrants:
            pile.append(i)
