def calculer(texte):
    nombres = []
    operateurs = []  # "+", "-", "*", "(" ou "~" (le signe moins)
    priorite = {"+": 1, "-": 1, "*": 2, "~": 3}

    def appliquer():
        op = operateurs.pop()
        if op == "~":
            nombres.append(-nombres.pop())
            return
        b = nombres.pop()
        a = nombres.pop()
        nombres.append(a + b if op == "+" else a - b if op == "-" else a * b)

    attend_un_nombre = True  # vrai au début, après "(" et après un opérateur
    i = 0
    while i < len(texte):
        c = texte[i]
        if c == " ":
            i += 1
        elif "0" <= c <= "9":
            n = 0
            while i < len(texte) and "0" <= texte[i] <= "9":
                n = n * 10 + int(texte[i])
                i += 1
            nombres.append(n)
            attend_un_nombre = False
        elif c == "(":
            operateurs.append(c)
            attend_un_nombre = True
            i += 1
        elif c == ")":
            while operateurs[-1] != "(":
                appliquer()
            operateurs.pop()
            attend_un_nombre = False
            i += 1
        elif c == "-" and attend_un_nombre:
            operateurs.append("~")
            i += 1
        else:
            while operateurs and operateurs[-1] != "(" and priorite[operateurs[-1]] >= priorite[c]:
                appliquer()
            operateurs.append(c)
            attend_un_nombre = True
            i += 1
    while operateurs:
        appliquer()
    return nombres[0]
